    private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
    private JSONObject payload(Object... values){JSONObject p=new JSONObject();try{for(int i=0;i+1<values.length;i+=2)p.put(String.valueOf(values[i]),values[i+1]);}catch(Exception ignored){}return p;}
    private JSONObject resultObj(JSONObject r){JSONObject q=r.optJSONObject("result");return q==null?r:q;}
    private JSONObject nested(JSONObject source,String key){JSONObject value=source==null?null:source.optJSONObject(key);return value==null?source:value;}
    private double number(JSONObject o,String... keys){if(o==null)return 0;for(String key:keys){Object value=o.opt(key);if(value instanceof Number)return ((Number)value).doubleValue();if(value instanceof String)try{return Double.parseDouble((String)value);}catch(Exception ignored){}}return 0;}
    private int integer(JSONObject o,String... keys){return (int)number(o,keys);}
    private String money(double value){return String.format(Locale.US,"%.2f",value);}
    private String objectName(JSONObject parent,String key,String fallback){JSONObject o=parent==null?null:parent.optJSONObject(key);return o==null?fallback:o.optString("name",fallback);}
    private String tripValue(JSONObject ticket,String key,String fallback){JSONObject trip=ticket==null?null:ticket.optJSONObject("trip");return trip==null?ticket.optString(key,fallback):trip.optString(key,ticket.optString(key,fallback));}
    private boolean allowed(String key){return capabilities.optBoolean(key,false);}
    private boolean hasRole(String role){for(int i=0;i<roles.length();i++)if(role.equalsIgnoreCase(roles.optString(i)))return true;return false;}

