    private void loadSeatMap(int trip,int origin,int destination,LinearLayout rows,TextView status,String[] selected,Button[] selectedButton,Button create){api.call("/api/nbc/v1/mobile/seats",payload("trip_id",trip,"origin_id",origin,"destination_id",destination),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->{JSONObject source=resultObj(r);JSONArray seats=source.optJSONArray("seats");rows.removeAllViews();if(seats==null||seats.length()==0){status.setText("No selectable seats were returned for this trip.");return;}status.setText(source.optString("layout","NBC coach")+" • "+source.optInt("available_seats")+" available\nGreen: available  •  Gray: unavailable  •  Teal: selected");int currentRow=-1;LinearLayout row=null;for(int i=0;i<seats.length();i++){JSONObject seat=seats.optJSONObject(i);if(seat==null)continue;int rowNo=seat.optInt("row",-1);if(row==null||rowNo!=currentRow){row=new LinearLayout(MainActivity.this);row.setGravity(Gravity.CENTER);rows.addView(row,new LinearLayout.LayoutParams(-1,dp(54)));currentRow=rowNo;}if("C".equalsIgnoreCase(seat.optString("column"))){Space aisle=new Space(MainActivity.this);row.addView(aisle,new LinearLayout.LayoutParams(dp(22),1));}String seatNo=seat.optString("seat_no",seat.optString("number","—")),seatState=seat.optString("status","unavailable");boolean available="available".equalsIgnoreCase(seatState);Button b=btn(seatNo,false);b.setTextSize(13);b.setEnabled(available);if(!available){b.setTextColor(MUTED);b.setAlpha(.45f);}else b.setOnClickListener(v->{if(selectedButton[0]!=null)selectedButton[0].setBackgroundResource(R.drawable.secondary_button);selected[0]=seatNo;selectedButton[0]=b;b.setBackgroundResource(R.drawable.primary_button);b.setTextColor(Color.WHITE);create.setEnabled(true);create.setText("Create booking • Seat "+seatNo);});LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(58),dp(48));bp.setMargins(dp(3),dp(2),dp(3),dp(2));row.addView(b,bp);}});}public void error(Exception e){runOnUiThread(()->status.setText("Seat map unavailable: "+message(e)));}});}
    private void recheckAndCreateBooking(int trip,int origin,int destination,String name,String phone,String seatNo,Button create){api.call("/api/nbc/v1/mobile/seats",payload("trip_id",trip,"origin_id",origin,"destination_id",destination),new ApiClient.Callback(){public void done(JSONObject r){JSONObject source=resultObj(r);JSONArray seats=source.optJSONArray("seats");boolean available=false;if(seats!=null)for(int i=0;i<seats.length();i++){JSONObject seat=seats.optJSONObject(i);if(seatNo.equalsIgnoreCase(seat.optString("seat_no"))&&"available".equalsIgnoreCase(seat.optString("status"))){available=true;break;}}boolean seatAvailable=available;runOnUiThread(()->{if(!seatAvailable){create.setEnabled(true);create.setText("Choose another seat");toast("Seat "+seatNo+" is no longer available. Refresh and select another seat.");return;}createBooking(trip,origin,destination,name,phone,seatNo,create);});}public void error(Exception e){runOnUiThread(()->{create.setEnabled(true);create.setText("Create booking • Seat "+seatNo);toast(message(e));});}});}
