    private void bookingCreated(JSONObject source,String seatNo){JSONObject booking=nested(source,"booking");int bookingId=integer(booking,"booking_id","id");String bookingNo=booking.optString("booking_no",booking.optString("name",source.optString("booking_no","NBC booking")));shell("Booking created");add(h1("Your seat is reserved"));cardResult(bookingNo,"Seat "+seatNo+" • Complete payment to receive your boarding ticket.");if(bookingId>0){Button pay=btn("Pay now",true);pay.setOnClickListener(v->paymentOptions("booking_id",bookingId,bookingNo));add(pay);}Button view=btn("View all bookings",false);view.setOnClickListener(v->bookings());add(view);}
