    private void myTrips(){if(!api.loggedIn()){login(false);return;}shell("My trips");add(h1("Your tickets"));add(small("Upcoming and previous NBC journeys linked to your passenger account."));api.call("/api/nbc/v1/passenger/tickets",payload("limit",200),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->{JSONArray a=array(r,"tickets");if(a==null||a.length()==0){cardResult("NO TRIPS YET","Book a journey from Home and your tickets will appear here.");return;}for(int i=0;i<a.length();i++){JSONObject t=a.optJSONObject(i);LinearLayout c=card();TextView route=txt(ticketBoarding(t)+"  →  "+ticketDestination(t),18,NAVY);route.setTypeface(null,1);c.addView(route);c.addView(small(tripValue(t,"departure","Departure pending")+" • Seat "+t.optString("seat","—")));c.addView(txt(t.optString("state","ticket").toUpperCase(Locale.US),12,TEAL));Button open=btn("Open boarding pass",false);open.setOnClickListener(v->showTicket(t));c.addView(open);add(c);}});}public void error(Exception e){runOnUiThread(()->cardResult("UNABLE TO LOAD TRIPS",message(e)));}});}
    private void showTicket(JSONObject t){shell("My ticket");LinearLayout c=tealCard();c.addView(txt("NATIONAL BUS COMPANY",11,Color.rgb(215,231,232)));TextView title=txt("Boarding pass",25,Color.WHITE);title.setTypeface(null,1);c.addView(title);add(c);add(txt("ROUTE",11,TEAL));TextView route=txt(ticketBoarding(t)+"  →  "+ticketDestination(t),19,NAVY);route.setTypeface(null,1);add(route);add(txt("DEPARTURE",11,TEAL));add(txt(tripValue(t,"departure","Upcoming service"),16,NAVY));JSONObject trip=t.optJSONObject("trip"),bus=trip==null?null:trip.optJSONObject("bus");if(bus!=null)add(small("Bus "+bus.optString("fleet_no",bus.optString("name","To be assigned"))+" • Run "+t.optString("run_number","—")));LinearLayout info=new LinearLayout(this);info.addView(infoCell("SEAT",t.optString("seat","—")),new LinearLayout.LayoutParams(0,-2,1));info.addView(infoCell("TICKET",t.optString("ticket_no","NBC ticket")),new LinearLayout.LayoutParams(0,-2,1));add(info);LinearLayout qr=card();qr.setGravity(Gravity.CENTER);String token=t.optString("qr_token",t.optString("ticket_no","NBC ticket"));ImageView qrImage=new ImageView(this);qrImage.setImageBitmap(qrBitmap(token,dp(210)));qrImage.setScaleType(ImageView.ScaleType.FIT_CENTER);qr.addView(qrImage,new LinearLayout.LayoutParams(-1,dp(220)));qr.addView(small("Show this ticket at boarding"));add(qr);LinearLayout state=card();state.setBackgroundColor(Color.rgb(229,246,240));state.addView(txt("✓  "+t.optString("state","Ticket ready").toUpperCase(Locale.US),16,TEAL));add(state);}
    private LinearLayout infoCell(String title,String value){LinearLayout x=box();x.addView(txt(title,11,TEAL));TextView v=txt(value,17,NAVY);v.setTypeface(null,1);x.addView(v);return x;}
    private void ticketStatus(){shell("Ticket status");add(h1("Verify your ticket"));add(small("Enter the NBC QR token or ticket number."));EditText code=field("NBCQR… or NBC-2026-…");add(code);Button check=btn("Check ticket",true);add(check);check.setOnClickListener(v->{try{check.setEnabled(false);api.call("/api/nbc/v1/traveler/ticket_status",new JSONObject().put("token",code.getText().toString().trim()),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->{check.setEnabled(true);JSONObject q=r.optJSONObject("result");if(q!=null&&q.optJSONObject("ticket")!=null)showTicket(q.optJSONObject("ticket"));else cardResult("TICKET RESPONSE",r.toString());});}public void error(Exception e){runOnUiThread(()->{check.setEnabled(true);toast(message(e));});}});}catch(Exception e){toast(message(e));}});}
    private void board(){shell("Station boards");add(h1("Live station boards"));add(small("Choose a terminal and view current arrivals or departures."));Spinner station=new Spinner(this),mode=new Spinner(this);add(txt("TERMINAL",11,TEAL));add(station);add(txt("BOARD",11,TEAL));mode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Departures","Arrivals","Both"}));add(mode);TextView status=small("Loading terminals…");add(status);Spinner unused=new Spinner(this);loadStops(station,unused,status);Button load=btn("View live board",true);add(load);load.setOnClickListener(v->{if(station.getSelectedItem()==null){toast("Select a terminal.");return;}String selectedMode=mode.getSelectedItem().toString().toLowerCase(Locale.US);try{api.call("/api/nbc/status_board",new JSONObject().put("terminal",station.getSelectedItem().toString()).put("mode",selectedMode).put("limit",120),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->renderBoard(r,selectedMode));}public void error(Exception e){runOnUiThread(()->toast(message(e)));}});}catch(Exception e){toast(message(e));}});}
    private void renderBoard(JSONObject r,String mode){shell("Station boards");add(h1(mode.substring(0,1).toUpperCase(Locale.US)+mode.substring(1)));JSONObject result=r.optJSONObject("result");JSONObject source=result==null?r:result;String terminal=source.optString("terminal","NBC terminal");add(small(terminal+" • Updated "+source.optString("generated_at","now")));JSONArray a=source.optJSONArray("trips");if(a==null||a.length()==0){cardResult("NO BOARD SERVICES","No "+mode+" are currently listed for this terminal.");return;}for(int i=0;i<a.length();i++){JSONObject z=a.optJSONObject(i);String boardTime=z.optString("actual","");if(boardTime.isEmpty()||"false".equalsIgnoreCase(boardTime))boardTime=z.optString("scheduled","—");LinearLayout c=card();TextView time=txt(boardTime,18,NAVY);time.setTypeface(null,1);c.addView(time);c.addView(small(z.optString("run_number","NBC run")));TextView route=txt(z.optString("origin")+"  →  "+z.optString("destination"),16,NAVY);route.setTypeface(null,1);c.addView(route);c.addView(txt(z.optString("status_label",z.optString("status","ON TIME")),13,TEAL));add(c);}}
    private void bookings(){if(!api.loggedIn()){login(false);return;}shell("Bookings");add(h1("Your bookings"));add(small("Review balances, pay securely, and refresh tickets after NBC confirms payment."));api.call("/api/nbc/v1/mobile/bookings",payload("limit",200),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->{JSONArray a=array(r,"bookings");if(a==null||a.length()==0){cardResult("NO BOOKINGS","Search for a journey from Home to create a booking.");return;}for(int i=0;i<a.length();i++){JSONObject b=a.optJSONObject(i);LinearLayout c=card();TextView no=txt(b.optString("booking_no",b.optString("name","NBC booking")),18,NAVY);no.setTypeface(null,1);c.addView(no);c.addView(small(b.optString("state","draft").toUpperCase(Locale.US)+" • "+integer(b,"ticket_count","tickets_count")+" ticket(s)"));double total=number(b,"total","amount_total","total_amount","amount"),balance=number(b,"balance","amount_due","balance_due","remaining_amount");String currency=b.optString("currency","BZD");c.addView(txt(currency+" "+money(total)+" • Balance "+money(balance),14,TEAL));int bookingId=integer(b,"booking_id","id");Button open=btn(balance>0?"Pay now":"Open booking",balance>0);open.setOnClickListener(v->{if(balance>0)paymentOptions("booking_id",bookingId,no.getText().toString());else bookingDetail(bookingId);});c.addView(open);add(c);}});}public void error(Exception e){runOnUiThread(()->cardResult("BOOKINGS UNAVAILABLE",message(e)));}});}
    private void bookingDetail(int bookingId){shell("Booking details");add(h1("Booking summary"));api.call("/api/nbc/v1/mobile/booking",payload("booking_id",bookingId),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->{JSONObject b=nested(resultObj(r),"booking");double total=number(b,"total","amount_total","total_amount","amount"),balance=number(b,"balance","amount_due","balance_due","remaining_amount");cardResult(b.optString("booking_no",b.optString("name","NBC booking")),b.optString("state","draft").toUpperCase(Locale.US)+"\n"+b.optString("currency","BZD")+" "+money(total)+" • Balance "+money(balance));if(balance>0){Button pay=btn("Pay now",true);pay.setOnClickListener(v->paymentOptions("booking_id",bookingId,b.optString("booking_no","Booking")));add(pay);}});}public void error(Exception e){runOnUiThread(()->cardResult("BOOKING UNAVAILABLE",message(e)));}});}
    private void payments(){if(!api.loggedIn()){login(false);return;}shell("Payments");add(h1("Payment history"));add(small("Payment status is confirmed by NBC and the selected payment provider."));api.call("/api/nbc/v1/mobile/payments",payload("limit",200),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->{JSONArray a=array(r,"payments");if(a==null||a.length()==0){cardResult("NO PAYMENTS","Confirmed and pending payments will appear here.");return;}for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);LinearLayout c=card();TextView amount=txt(p.optString("currency","BZD")+" "+money(number(p,"amount","total")),20,NAVY);amount.setTypeface(null,1);c.addView(amount);c.addView(small(p.optString("method",p.optString("provider","Payment"))+" • "+p.optString("date","")));c.addView(txt(p.optString("state","pending").toUpperCase(Locale.US),12,TEAL));int recordId=integer(p,"record_id","payment_record_id","id");if(recordId>0){Button refresh=btn("Refresh status",false);refresh.setOnClickListener(v->paymentStatus(recordId));c.addView(refresh);}add(c);}});}public void error(Exception e){runOnUiThread(()->cardResult("PAYMENTS UNAVAILABLE",message(e)));}});}
    private void paymentOptions(String ownerKey,int ownerId,String reference){if(ownerId<=0){toast("NBC did not return a valid record ID.");return;}shell("Pay now");add(h1(reference));add(small("Choose a payment method. NBC confirms every payment on the server before issuing a ticket."));JSONObject request=payload(ownerKey,ownerId);api.call("/api/nbc/v1/passenger/payment/options",request,new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->{JSONObject source=resultObj(r);double due=number(source,"amount_due","balance","amount");add(txt(source.optString("currency","BZD")+" "+money(due),28,NAVY));add(small("Amount due"));JSONArray methods=source.optJSONArray("methods");Set<String> shown=new HashSet<>();if(methods!=null)for(int i=0;i<methods.length();i++){JSONObject method=methods.optJSONObject(i);if(method==null)continue;String code=method.optString("code"),name=method.optString("name",methodName(code));shown.add(code);paymentMethodRow(ownerKey,ownerId,code,name,method.optString("flow"),method.optBoolean("enabled",false));}for(String code:new String[]{"digiwallet","ekyash","belizebank"})if(!shown.contains(code))paymentMethodRow(ownerKey,ownerId,code,methodName(code),"provider",false);add(h1("Pay at an NBC station"));action("$","Cash","Keep this booking reserved and pay cash with an authorized station agent.",v->payAtStationInfo("Cash"));action("▣","Card at station/device","Pay by supported card terminal with an authorized station agent.",v->payAtStationInfo("Card"));action("♙","NBC customer account / credit","Available only when NBC has approved account or credit terms.",v->payAtStationInfo("NBC account / credit"));});}public void error(Exception e){runOnUiThread(()->{cardResult("ONLINE METHODS UNAVAILABLE",message(e));add(h1("Pay at an NBC station"));action("$","Cash","Pay an authorized station agent.",v->payAtStationInfo("Cash"));action("▣","Card at station/device","Pay using a supported station terminal.",v->payAtStationInfo("Card"));action("♙","NBC customer account / credit","For approved NBC accounts only.",v->payAtStationInfo("NBC account / credit"));});}});}
    private void paymentMethodRow(String ownerKey,int ownerId,String code,String name,String flow,boolean enabled){if(enabled)action("$",name,paymentDescription(code,flow),v->initiatePayment(ownerKey,ownerId,code));else{LinearLayout c=card();TextView title=txt(name,17,NAVY);title.setTypeface(null,1);c.addView(title);c.addView(small("Currently unavailable • NBC provider configuration required"));add(c);}}
    private void payAtStationInfo(String method){shell("Pay at station");add(h1(method));cardResult("BOOKING REMAINS RESERVED","Show your booking number to an authorized NBC station agent. The Passenger app cannot mark cash, station card, or account payments as paid.");Button bookingsButton=btn("Return to bookings",true);bookingsButton.setOnClickListener(v->bookings());add(bookingsButton);}
    private String paymentDescription(String code,String flow){if("digiwallet".equals(code))return "Send a secure DigiWallet TAC/OTP to your mobile number.";if("ekyash".equals(code))return "Start an E-Kyash provider payment.";if("belizebank".equals(code))return "Pay through Belize Bank’s hosted secure checkout.";return flow+" payment";}
    private void initiatePayment(String ownerKey,int ownerId,String method){if("digiwallet".equals(method)){shell("DigiWallet");add(h1("Send payment code"));add(small("Enter the mobile number registered with DigiWallet."));EditText phone=field("Mobile phone");add(phone);Button send=btn("Send TAC / OTP",true);add(send);send.setOnClickListener(v->callInitiate(ownerKey,ownerId,method,phone.getText().toString().trim()));return;}callInitiate(ownerKey,ownerId,method,"");}
    private void callInitiate(String ownerKey,int ownerId,String method,String phone){JSONObject request=payload(ownerKey,ownerId,"method",method);try{if(!phone.isEmpty())request.put("payer_phone",phone);}catch(Exception ignored){}api.call("/api/nbc/v1/passenger/payment/initiate",request,new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->renderInitiatedPayment(resultObj(r),method));}public void error(Exception e){runOnUiThread(()->toast(message(e)));}});}
    private void renderInitiatedPayment(JSONObject source,String method){JSONObject payment=nested(source,"payment");int recordId=integer(payment,"record_id","payment_record_id","id");if("digiwallet".equals(method)){shell("Confirm DigiWallet");add(h1("Enter your TAC / OTP"));add(small(payment.optString("message","DigiWallet sent a confirmation code to your phone.")));EditText tac=field("TAC / OTP");tac.setInputType(InputType.TYPE_CLASS_NUMBER);add(tac);Button confirm=btn("Confirm payment",true);add(confirm);confirm.setOnClickListener(v->confirmDigiWallet(recordId,tac.getText().toString().trim()));return;}String url=payment.optString("payment_url",source.optString("payment_url",""));if(!url.isEmpty()&&!"false".equalsIgnoreCase(url)){paymentWeb(url,recordId,method);return;}shell("Payment started");add(h1(methodName(method)+" payment"));cardResult("PAYMENT PENDING",payment.optString("message","NBC created the payment. Refresh its status after completing the provider instructions."));Button refresh=btn("Refresh payment status",true);refresh.setOnClickListener(v->paymentStatus(recordId));add(refresh);}
    private String methodName(String method){if("digiwallet".equals(method))return "DigiWallet";if("ekyash".equals(method))return "E-Kyash";if("belizebank".equals(method))return "Belize Bank";return method;}
    private void confirmDigiWallet(int recordId,String tac){if(recordId<=0||tac.isEmpty()){toast("Enter the DigiWallet TAC / OTP.");return;}api.call("/api/nbc/v1/passenger/payment/digiwallet/confirm",payload("payment_record_id",recordId,"tac",tac),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->showPaymentResult(resultObj(r),recordId));}public void error(Exception e){runOnUiThread(()->toast(message(e)));}});}
    private void paymentStatus(int recordId){if(recordId<=0){toast("Payment reference is unavailable.");return;}api.call("/api/nbc/v1/passenger/payment/status",payload("payment_record_id",recordId),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->showPaymentResult(resultObj(r),recordId));}public void error(Exception e){runOnUiThread(()->toast(message(e)));}});}
    private void showPaymentResult(JSONObject source,int recordId){JSONObject payment=nested(source,"payment");shell("Payment status");String state=payment.optString("state",source.optString("state","pending"));add(h1("Payment "+state));cardResult(payment.optString("payment_id","NBC payment"),payment.optString("message",payment.optString("provider_message","NBC is checking the provider status."))+"\n"+payment.optString("currency","BZD")+" "+money(number(payment,"amount")));if("paid".equalsIgnoreCase(state)||"posted".equalsIgnoreCase(state)||"done".equalsIgnoreCase(state)){Button tickets=btn("Open my tickets",true);tickets.setOnClickListener(v->myTrips());add(tickets);}else{Button refresh=btn("Refresh status",true);refresh.setOnClickListener(v->paymentStatus(recordId));add(refresh);}}
    private void paymentWeb(String url,int recordId,String method){atRoot=false;LinearLayout root=box();root.setBackgroundColor(ICE);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(12),dp(10),dp(12),dp(10));bar.setBackgroundColor(NAVY);Button back=btn("‹",false);back.setTextColor(Color.WHITE);back.setTextSize(30);back.setBackgroundColor(Color.TRANSPARENT);bar.addView(back,new LinearLayout.LayoutParams(dp(44),dp(50)));TextView title=txt(methodName(method)+" secure payment",18,Color.WHITE);title.setTypeface(null,1);bar.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button done=btn("Check status",false);done.setTextColor(Color.WHITE);done.setBackgroundColor(Color.TRANSPARENT);bar.addView(done,new LinearLayout.LayoutParams(dp(112),dp(48)));root.addView(bar);WebView web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.setWebViewClient(new WebViewClient());web.loadUrl(url);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);back.setOnClickListener(v->{if(web.canGoBack())web.goBack();else bookings();});done.setOnClickListener(v->paymentStatus(recordId));}
    private void passes(){if(!api.loggedIn()){login(false);return;}shell("Bus Passes");add(h1("Your Bus Passes"));add(small("NBC validates pass dates, route coverage, payment state, and ride limits on the server."));Button buy=btn("Purchase a Bus Pass",true);buy.setOnClickListener(v->passTypes());add(buy);api.call("/api/nbc/v1/passenger/passes",new JSONObject(),new ApiClient.Callback(){public void done(JSONObject r){runOnUiThread(()->{JSONArray a=array(r,"passes");if(a==null||a.length()==0){cardResult("NO BUS PASSES","Choose Purchase a Bus Pass to view available products.");return;}for(int i=0;i<a.length();i++){JSONObject p=a.optJSONObject(i);LinearLayout c=card();TextView name=txt(p.optString("type",p.optString("pass_no","NBC Bus Pass")),18,NAVY);name.setTypeface(null,1);c.addView(name);c.addView(small(p.optString("pass_no","")+" • "+p.optString("valid_from","—")+" to "+p.optString("valid_to","—")));String paymentState=p.optString("payment_state","pending");c.addView(txt(p.optString("state","draft").toUpperCase(Locale.US)+" • Payment "+paymentState.toUpperCase(Locale.US)+" • "+p.optInt("rides_used")+" rides used",12,TEAL));int passId=integer(p,"pass_id","id");if(!"paid".equalsIgnoreCase(paymentState)){Button pay=btn("Pay for Bus Pass",true);pay.setOnClickListener(v->paymentOptions("pass_id",passId,p.optString("pass_no","Bus Pass")));c.addView(pay);}Button open=btn("Open pass and QR",false);open.setOnClickListener(v->showPass(p));c.addView(open);add(c);}});}public void error(Exception e){runOnUiThread(()->cardResult("PASSES UNAVAILABLE",message(e)));}});}
