    private void operationsHome(){shell("Operations");add(txt("Good afternoon",25,NAVY));add(small("Your tools are matched to the NBC roles assigned to this account."));loadRunHero();add(txt("Quick actions",20,NAVY));LinearLayout quick=new LinearLayout(this);quick.setGravity(Gravity.CENTER);quick.addView(quickAction("□","Scan ticket",v->scan()),new LinearLayout.LayoutParams(0,dp(85),1));quick.addView(quickAction("$","Sell ticket",v->conductorSale()),new LinearLayout.LayoutParams(0,dp(85),1));quick.addView(quickAction("⌖","Live GPS",v->gps()),new LinearLayout.LayoutParams(0,dp(85),1));add(quick);add(txt("Run progress",20,NAVY));progressCard();add(small("NBC Operations v1.7.8 • API v9.12.2"));}
